style.css:
@-moz-document domain("pinterest.com") {
/* 1. FONDO SEGURO: Rojo Vibrante con Puntos Blancos Pequeños (Código puro, no se bloquea) */
    body, html, #initial-focus-container, [data-test-id="grid"], .App, main, [style*="background-color"] {
        background-color: #E60023 !important; /* Rojo de base */
        background-image: radial-gradient(#FFFFFF 12%, transparent 12%),
                          radial-gradient(#FFFFFF 12%, transparent 12%) !important;
        background-size: 24px 24px !important; /* Puntos pequeños y coquetos */
        background-position: 0 0, 12px 12px !important; /* Alineación perfecta */
        background-attachment: fixed !important;
    }

    /* 2. ICONOS DEL MENÚ: Rojos con circulito blanco de fondo */
    svg, path, circle, [role="img"], [data-test-id="navigation-bar"] svg, .gUZ, .U90 {
        fill: #E60023 !important;
        color: #E60023 !important;
    }
    [data-test-id="navigation-bar"] a, 
    [data-test-id="navigation-bar"] button,
    [aria-label*="Inicio"], [aria-label*="Home"], [aria-label*="Mensajes"], [aria-label*="Notificaciones"] {
        background-color: #FFFFFF !important;
        border: 2px solid #FFF59D !important;
        border-radius: 50% !important;
        padding: 6px !important;
    }

    /* 3. BARRA DE BÚSQUEDA: Amarilla con letras cursivas negras */
    [data-test-id="search-box-container"], form[role="search"], .RNNXgb, input[type="text"] {
        background-color: #FFF59D !important;
        border: 2px solid #FFFFFF !important;
        border-radius: 24px !important;
    }
    input[type="text"], .gLFyf, [data-test-id="search-box-input"] {
        color: #000000 !important;
        font-family: 'Lucida Handwriting', 'Corsiva Hebrew', 'Georgia', cursive !important;
        font-style: italic !important;
        font-size: 16px !important;
    }
    [data-test-id="search-box-search-icon"] svg, [data-test-id="search-box-search-icon"] path {
        fill: #000000 !important;
        color: #000000 !important;
    }

    /* 4. INFORMACIÓN DE LOS PINES: Letras Cursivas Negras limpias (Sin recuadro) */
    [data-test-id="pin-title"], 
    [data-test-id="official-user-name"],
    h1, h2, h3, p, span, .text, .title {
        color: #000000 !important;
        font-family: 'Lucida Handwriting', 'Corsiva Hebrew', 'Georgia', cursive !important;
        font-style: italic !important;
        background-color: transparent !important;
        background: transparent !important;
        border: none !important;
        padding: 4px 0px !important;
        /* Delineado blanco fino para que resalte hermoso sobre el rojo con puntos */
        text-shadow: -1px -1px 0 #FFFFFF, 1px -1px 0 #FFFFFF, -1px 1px 0 #FFFFFF, 1px 1px 0 #FFFFFF !important;
    }
}
